// Public types. Spec §3.1 (docs/spec/v1.md). Keep in sync with the spec.

/** UUID generated by the library. */
export type RecordingId = string;

/** JSON-serialisable, opaque to the library. */
export type Metadata = Record<string, unknown>;

export type UploadTarget = {
  url: string;
  /** Sent on every Chunk request. */
  headers?: Record<string, string>;
};

export type UploadUrlProvider = (ctx: {
  recordingId: RecordingId;
  metadata?: Metadata;
}) => Promise<UploadTarget>;

export type StartRecordingOptions = {
  uploadUrlProvider: UploadUrlProvider;
  /** Default `true`. */
  keepRecordingFile?: boolean;
  /** Default `true`. */
  allowCellular?: boolean;
  metadata?: Metadata;
  /** Default: none. */
  maxDurationSeconds?: number;
  /** Bytes, multiple of 256 KiB. Default 1 MiB. */
  minChunkSize?: number;
};

export type StopReason =
  'user' | 'interrupted' | 'lowStorage' | 'maxDuration' | 'backgrounded';

export type UploadState =
  | 'waitingForUrl'
  | 'uploading'
  | 'paused'
  | 'finalizing'
  | 'completed'
  | 'failed';

export type PauseReason =
  | 'offline'
  | 'backgrounded'
  | 'deprioritized'
  | 'awaitingWifi'
  | 'awaitingResume';

export type Recording = {
  id: RecordingId;
  metadata?: Metadata;
  isLive: boolean;
  /** `true` = Interrupted Recording (app killed mid-capture). */
  interrupted: boolean;
  /** Set once Finished. */
  stopReason?: StopReason;
  /** `null` once deleted. */
  filePath: string | null;
  recordedBytes: number;
  committedOffset: number;
  uploadState: UploadState;
  pauseReason?: PauseReason;
  error?: UploadError;
  keepRecordingFile: boolean;
  allowCellular: boolean;
  /** ISO 8601. */
  createdAt: string;
};

export type UploadError = {
  code: 'urlProviderFailed' | 'urlRejected' | 'fileMissing' | 'unknown';
  httpStatus?: number;
  message: string;
};

export type PermissionState =
  'granted' | 'denied' | 'undetermined' | 'restricted';

export type PermissionStatus = {
  camera: PermissionState;
  microphone: PermissionState;
};
